from pathlib import Path
import json
p=Path(__file__).resolve().parents[1]/'src/curriculum.json'
d=json.loads(p.read_text());d['weeks']=d['weeks'][:16]
# Stable lesson IDs and all existing weekly notes remain untouched.
links={1:[7,14],2:[11,14],3:[27,29],4:[22,26],5:[112,118],6:[15,18],7:[19,21],8:[33,35],9:[119,126],10:[35,35],11:[36,38],12:[30,32],13:[239,249],14:[44,45],15:[44,45],16:[49,51]}
for w in d['weeks']:
 for l in w['lessons']:l['bookPages']=links[w['id']]
new=[
(17,'SQL para provar o estado dos dados','SQL','Básico',['G3','G5','G7'],'Investigue registros, relacionamentos e transações com resultados reproduzíveis.',[
('SQLite, dados e consultas confiáveis',[27,27],'Uma resposta da interface não comprova persistência. SQL fornece um oráculo independente; comece por um banco local descartável, schema explícito e dados sintéticos.','Baixe lab_sql.py no Meu livro. Execute com py lab_sql.py e explore as tabelas usuarios e pedidos no SQLite do Python. Escreva SELECT, WHERE e ORDER BY para usuários ativos.','O laboratório termina com 5 verificações passando; sua consulta retorna Ana e Caio, ordenados, sem expor usuários inativos.'),
('JOIN, agregações e reconciliação',[28,29],'INNER JOIN mostra correspondências; LEFT JOIN preserva registros sem associação. COUNT(*) e COUNT(coluna) tratam NULL de forma diferente.','No banco do laboratório, agrupe pedidos por usuário, calcule SUM e AVG em centavos e encontre o usuário sem pedidos com LEFT JOIN. Faça primeiro sua consulta, depois consulte os exercícios SQL 003–010.','Ana possui dois pedidos somando 6000 centavos, Bia um pedido de 1500 e Caio nenhum. Explique como evitou duplicar totais no JOIN.'),
('Integridade, duplicatas e dados ausentes',[180,185],'Constraints previnem estados inválidos; uma consulta também pode revelar regras ausentes. O resultado vazio só significa sucesso quando o critério é explícito.','Escreva consultas para emails duplicados, pedidos órfãos e valores negativos. Em transações separadas, tente inserir cada defeito; registre quais constraints o bloqueiam e restaure os dados.','Cada risco possui consulta, seed e resultado esperado. Diferencie um defeito impedido pelo banco de um defeito detectado pela consulta.'),
('Transações, migração e rollback',[186,190],'Atomicidade exige observar commit e rollback. Scripts do PDF usam recursos de PostgreSQL: INTERVAL, funções e datas precisam ser adaptados ao SQLite.','Crie uma transação que altera um pedido, force uma falha e aplique rollback. Simule uma migração adicionando coluna opcional e compare contagens e totais antes/depois.','O rollback restaura o valor inicial. A migração preserva três pedidos e o total de 7500 centavos. Entregue uma tabela de compatibilidade SQL.'),
('SLA, auditoria e evidências SQL',[191,197],'Agregações e percentis ajudam a encontrar desvios; limiares são critérios do projeto e não leis universais. Dados e intervalo de medição precisam ser comparáveis.','Escolha dois exercícios avançados SQL, defina schema e massa mínima e traduza para seu banco. Inclua uma anomalia controlada e descreva a consulta esperada antes da execução.','Duas consultas detectam as falhas inseridas. Anexe script, seed e resultado ao G7; justifique um limiar próprio para G8, sem copiar limites regulatórios do exemplo.')]),
(18,'Web e API em JavaScript e TypeScript','Ecossistema','Intermediário',['G3','G6','G7'],'Compare ferramentas e adapte gabaritos para projetos isolados e sustentáveis.',[
('Da sintaxe Python ao Playwright Test',[15,18],'O livro usa JavaScript nos testes web/API. Playwright Test pertence ao ecossistema Node; fixtures e await não são sintaxe Python. Use projetos separados.','Crie uma pasta de estudo com Node LTS compatível e npm init playwright@latest. Refaça o login estudado em Python em TypeScript, com locators por papel e label.','O teste compila, executa e falha ao alterar a credencial esperada. Registre versões, comando e uma comparação de fixtures Python/TS.'),
('Dez comportamentos web, um contrato',[54,66],'Login, checkbox, dropdown, tabela, modal e upload exigem oráculos diferentes. Um seletor que existe em um exemplo pode não existir na aplicação real.','Selecione três exercícios Web básicos no índice. Inspecione a página-alvo, reescreva os locators e implemente assertions observáveis. Use uma página local se o componente não existir.','Três testes independentes passam; uma falha controlada é detectada. Registre URL, página do livro e adaptação, sem executar todos os exemplos de uma vez.'),
('API: contrato, chave e isolamento',[112,118],'Exemplos ReqRes precisam seguir o contrato atual, incluindo autenticação. ID criado e persistência não podem ser supostos a partir de uma resposta mock.','Escolha dois exercícios API. Documente endpoint, headers e persistência usando a documentação atual; use Restful Booker com dados próprios ou API local quando adequado. Inclua um caso negativo.','Cada teste prepara e limpa seus dados. Nenhum ID depende de outro teste, nenhuma chave está no código e status + campos + regra de negócio são verificados.'),
('Mocks, contratos e execução paralela',[67,111],'Mock prova o comportamento diante de uma resposta controlada; integração prova a comunicação real. São evidências diferentes.','Selecione um exercício Web de interceptação e um de paralelismo. Simule uma falha de API na UI com route, depois execute dois testes sem compartilhar dados mutáveis.','O relatório distingue mock de integração. Os testes passam isolados e em paralelo e registram a falha esperada, sem usar retries para esconder a causa.'),
('Cypress, Selenium Grid, Karate e Rest Assured',[46,48],'Ferramentas têm linguagens e custos de manutenção distintos. Selenium Grid distribui sessões WebDriver; a escolha depende da base existente, integração e equipe.','Leia as referências oficiais e faça uma matriz com Playwright, Cypress, Selenium/Grid, Karate e Rest Assured. Para o seu contexto Python/VS Code, produza uma decisão arquitetural e um pequeno spike na alternativa mais relevante.','A matriz compara linguagem, runner, UI/API, distribuição e manutenção com fontes. O spike tem instruções e limitações; não precisa instalar todas as stacks.')]),
(19,'Mobile com Appium no Windows','Mobile','Intermediário',['G4','G5','G7','G8'],'Automatize Android e registre os limites de emulação e dispositivos.',[
('Preparar Android e Appium',[39,40],'Appium conecta um cliente a um servidor e um driver. No Windows, a prática local é Android com UiAutomator2; iOS local requer ambiente Apple compatível.','Use Node LTS, npm, Android Studio/SDK e JDK compatíveis com o driver. Instale Appium e UiAutomator2 seguindo o guia oficial, rode appium driver doctor uiautomator2 e adb devices. Se faltar tempo, encerre com diagnóstico e retome no sábado.','Registre versões e diagnóstico, sem fingir execução. Um emulador ou dispositivo aparece no adb; a sessão só é concluída após um smoke real ou uma pendência explícita.'),
('Primeiro smoke com locators estáveis',[198,204],'Capabilities definem aplicação e dispositivo; accessibility id e esperas por condição reduzem acoplamento. O PDF contém nomes de APK e IDs ilustrativos.','Escolha um APK próprio ou demo autorizado, registre sua origem e abra com Inspector. Adapte os exercícios Mobile 001 e 004, criando fixture pytest com driver.quit() no teardown.','Dois testes independentes observam a tela e um fluxo de login. O APK existe, IDs foram inspecionados e o driver é encerrado mesmo após uma assertion falhar.'),
('Permissões, GPS, câmera e biometria',[205,213],'Estados de permissão são parte da entrada do teste. Biometria e notificações dependem do dispositivo e da infraestrutura do app; simulação não prova entrega ponta a ponta.','Selecione dois cenários de permissão e localização. Execute permitir/negar no emulador com APIs suportadas pelo driver. Para push ou biometria sem suporte, documente o que falta e o teste de integração necessário.','Matriz registra versão Android, estado inicial e resultado. Diferencie teste simulado de integração real e não marque uma transmissão ADB como prova de push do provedor.'),
('Gestos, rede e estados do aplicativo',[214,230],'Gestos dependem de tamanho e orientação; salvar estado exige testar reinício, background e falhas de rede. Use comandos documentados do driver atual.','Escolha um gesto e um cenário de persistência do índice. Substitua sleeps por esperas de estado. Execute em duas orientações e com rede indisponível no ambiente de teste.','As evidências mostram quatro combinações, limpeza do estado e mensagens observáveis. Registre limitações do emulador e um cenário que exige aparelho real.'),
('Release mobile, acessibilidade e diagnóstico',[231,238],'Tempo observado em um emulador não é benchmark de aparelho real. Versão Android, targetSdk e condições de execução determinam permissões e comportamento.','Monte um smoke de até cinco fluxos, anexe screenshots nas falhas e registre duração. Revise contraste, foco, labels e permissões de mídia do Android 13+. Compare com um dispositivo real se disponível.','Relatório contém build, dispositivo/API, resultados e lacunas. Atualize G7/G8 com evidência real e declare o que continua sem avaliação, incluindo iOS.')]),
(20,'Robot Framework e BDD na prática','Robot e BDD','Intermediário',['G1','G5','G6'],'Expresse comportamento e mantenha a implementação técnica em seu lugar.',[
('Robot: ambiente e primeiro teste',[42,43],'Robot usa tabelas de keywords e bibliotecas Python. O ambiente virtual evita conflitos; não é necessário usar --break-system-packages no Windows.','Crie um venv separado, instale robotframework e baixe smoke.robot no Meu livro. Execute python -m robot -d reports smoke.robot e examine log.html e report.html.','O teste local passa. Mude o resultado esperado para provocar falha e explique o status de saída e os dois relatórios.'),
('Keywords, dados e biblioteca web',[42,43],'Keywords de domínio descrevem intenção; bibliotecas como SeleniumLibrary executam ações. Setup e teardown controlam ciclo de vida.','Instale SeleniumLibrary no venv. Implemente uma keyword de login e um caso negativo na demo autorizada; use waits explícitos, variáveis de ambiente e fechamento de browser.','O teste pode rodar sozinho, não usa senha real e gera relatório. Justifique quando keywords melhoram legibilidade em relação ao teste Python existente.'),
('Robot: API, banco e isolamento',[42,43],'RequestsLibrary e DatabaseLibrary têm contratos próprios; importar a biblioteca não cria sua API nem seu banco. Gerencie dependências e credenciais por ambiente.','Com documentação oficial das bibliotecas, escreva um teste GET na API de laboratório e uma consulta no banco local. Externalize URL e crie/limpe apenas sua massa.','Os dois testes validam valores esperados, encerram recursos e funcionam fora de ordem. Documente o driver de banco e as diferenças de sintaxe.'),
('BDD: exemplos antes do código',[44,45],'BDD é descoberta colaborativa e exemplos compartilhados; Gherkin é uma forma de expressá-los. Escrever passos de cliques não substitui discutir regras.','Escolha a regra de comissão Greenfield/Brownfield. Faça perguntas de descoberta, defina três exemplos com PO/Dev simulados e escreva Scenario Outline com valores de fronteira.','Given/When/Then usa linguagem de negócio; cada exemplo tem resultado calculado. Associe G1 e G5 e registre dúvidas ainda não resolvidas.'),
('Cucumber e rastreabilidade da regra',[44,45],'Step definitions conectam exemplos à implementação. Uma camada BDD só se justifica se facilitar colaboração e manutenção.','Em projeto Node separado, instale Cucumber conforme o guia oficial. Conecte um cenário de regra pura a uma função local, provoque uma falha e associe requisito, cenário e relatório.','Há uma execução verde e outra vermelha pelo motivo esperado. Compare custo com pytest parametrizado e decida se mantém BDD no projeto, com justificativa.')]),
(21,'Performance, segurança e qualidade em escala','Não funcionais','Avançado',['G2','G8','G9'],'Transforme métricas e riscos em critérios verificáveis no ambiente controlado.',[
('k6: medir antes de concluir',[46,47],'Checks validam respostas; thresholds estabelecem critérios de saída. p95, taxa de erro, VUs e duração descrevem aspectos diferentes.','Use o servidor mock local entregue e escreva um script k6 com 1 VU por 30s. Defina limiares didáticos, faça checks do status e meça p95. Rode apenas no seu localhost.','Guarde script, thresholds, resumo, ambiente e versão. A decisão de G8 menciona tamanho da amostra e não generaliza o resultado para produção.'),
('JMeter, carga e gargalos',[47,47],'Um plano de carga precisa de perfil, ritmo, dados e monitoramento. Gerador saturado pode parecer falha do sistema.','Desenhe um plano JMeter equivalente ao k6 e execute um pequeno caso local se tiver o Java exigido. Compare usuários, ramp-up, percentis e erro; não faça stress em demos públicas.','Uma tabela documenta equivalência, métricas e limitações. Há hipótese para um gargalo e um experimento de confirmação, não apenas um gráfico.'),
('OWASP, autorização e isolamento',[48,48],'Autenticação prova identidade; autorização limita operações e objetos. Testes de segurança dependem de escopo e contas de laboratório.','Desenhe casos para usuário A acessar recurso de B, token ausente, expiração e entrada inesperada em API local. Relacione-os ao WSTG e valide um bloqueio esperado com dois usuários sintéticos.','Casos registram resultado esperado, observado e evidência sem segredos. O bloqueio de um cenário não vira alegação de auditoria completa de segurança.'),
('Acessibilidade, contratos e resiliência',[103,111],'Acessibilidade combina automação e teclado/leitor; contratos e resiliência investigam riscos que E2E sozinho não cobre.','Faça navegação por teclado no projeto final, rode axe e investigue um resultado. Desenhe um contrato consumidor/provedor e simule uma resposta 503 com recuperação controlada.','Relatório separa avaliação humana de automática, identifica um risco de contrato e demonstra tratamento da indisponibilidade sem perda de dados.'),
('QAOps e gates com sinais úteis',[36,38],'Pipeline deve produzir evidências associadas a versão, ambiente e risco. Um retry verde não apaga uma falha inicial.','Revise os gates de CI do projeto: smoke, regressão, relatório e NFR. Use os prompts 33, 37 e 39 como rascunho, conferindo as sugestões com resultados reais.','Cada gate tem critério, responsável e artefato. Uma falha controlada bloqueia o fluxo esperado; desvios e flakiness têm ação e condição de reavaliação.')]),
(22,'Portfólio, entrevistas e revisão profissional','Carreira','Avançado',['G1','G2','G3','G4','G5','G6','G7','G8','G9'],'Conecte o estudo ao impacto e conclua uma revisão honesta das evidências.',[
('Diagnóstico e escolhas de carreira',[7,10],'Bloqueios diminuem com passos verificáveis e revisão do progresso. Escolher stack exige contexto de equipe e projeto, além da popularidade.','Refaça o diagnóstico do capítulo 1 e compare com seu início. Use o capítulo 13 para selecionar três lacunas observáveis e um próximo experimento de duas horas.','Seu plano descreve evidências já existentes, pontos a desenvolver e um foco. Não promete domínio de todas as ferramentas só por ler o livro.'),
('Entrevista técnica com demonstração',[49,51],'Uma boa resposta apresenta contexto, hipótese, decisão, evidência e limites. Saber um termo não equivale a demonstrar o comportamento.','Escolha cinco perguntas do capítulo 13 e responda antes de ler o comentário. Demonstre flakiness, fixture, POM, assertion e estratégia com exemplos do seu repositório.','Cada resposta aponta um artefato reproduzível. Registre uma resposta corrigida após a prática e um tópico que ainda precisa de estudo.'),
('Prompts como rascunhos revisáveis',[239,249],'Prompts de estratégia, código, diagnóstico e comunicação ajudam a elaborar hipóteses. A validação continua humana e baseada no projeto.','Use um prompt de código, um de análise e um de carreira. Forneça apenas contexto sintético, revise a saída e compare afirmações com os testes. Salve sua adaptação no índice do livro.','Três prompts possuem entrada, crítica, revisão e evidência. Remova afirmações sem prova e não copie resultados ou experiência que você não possui.'),
('Checklist profissional contextualizado',[250,251],'O checklist do livro é um ponto de partida. Percentuais de cobertura, número de smoke tests, POM e retries precisam de decisão por risco.','Revise os 36 itens do checklist no Meu livro. Registre atendimento ou pendência e associe ao gate relevante. Marque apenas os itens conferidos; explique os que não se aplicam nas notas da aula.','A revisão distingue evidência, pendência e não aplicabilidade. Nenhum checkbox aprova automaticamente um dos nove gates.'),
('Dossiê final: Greenfield e Brownfield',[252,256],'A rastreabilidade conecta requisitos, riscos, testes, defeitos e decisão. Glossário é apoio: explique termos com exemplos próprios e confira protocolos na documentação.','Atualize seu portfólio com README, setup Windows, relatório de dados, API, web e decisões BMAD. Revise separadamente G1–G9 para Greenfield e Brownfield e exporte o backup do QA Atlas.','Os 18 registros de gates têm decisão honesta; aprovações incluem commit, responsável e evidência. O README permite reproduzir o projeto e lista limitações, inclusive mobile ou cloud não executados.')])
]
for ident,title,topic,level,gates,goal,rows in new:
 w=dict(id=ident,title=title,goal=goal,topic=topic,level=level,gates=gates,lessons=[])
 for day,(name,pages,concept,challenge,criteria) in enumerate(rows,1):
  w['lessons'].append(dict(id=f'w{ident}d{day}',week=ident,day=day,title=name,topic=topic,level=level,concept=concept,challenge=challenge,criteria=criteria,bookPages=pages,evidence='Registre comando, versão, resultado e caminho do artefato. Indique qualquer parte não executada.',prompt=f'Aja como mentor de QA. Estou estudando {name} no Windows/VS Code. Meu objetivo é: {criteria} Peça minha hipótese antes de ajudar; dê uma pista por vez e não invente resultado de execução.',steps=['15 min · Revise a última evidência e defina a hipótese de hoje.',f'25 min · Leia as páginas {pages[0]}–{pages[1]} de apoio e a referência oficial. Se a faixa for longa, escolha apenas o exercício ligado ao desafio.','65 min · Execute um recorte do desafio, inspecione uma falha e registre o resultado.','15 min · Compare com o critério, salve a evidência e anote o próximo passo.']))
 d['weeks'].append(w)
p.write_text(json.dumps(d,ensure_ascii=False,indent=2))
print('Curriculum:',len(d['weeks']),'weeks',sum(len(w['lessons']) for w in d['weeks']),'lessons')
